"""Rendering helpers: human-readable by default, JSON on request.

Every renderer takes ``as_json`` so the same command can serve a person at a
terminal and a script piping into ``jq`` without a second code path.
"""

from __future__ import annotations

import json
from typing import Any

_STATEMENT_WIDTH = 60


def _json(payload: Any) -> str:
    if isinstance(payload, str):
        try:
            payload = json.loads(payload)
        except json.JSONDecodeError:
            return payload
    return json.dumps(payload, indent=2, ensure_ascii=False)


def _truncate(text: str, width: int = _STATEMENT_WIDTH) -> str:
    return text if len(text) <= width else text[: width - 1] + "…"


def _num(value: Any) -> str:
    """Render numeric scores to two decimals; pass anything else through."""
    if isinstance(value, bool):
        return str(value)
    if isinstance(value, (int, float)):
        return f"{value:.2f}"
    return str(value)


def _block(rows: list[tuple[str, Any]]) -> str:
    """Render label/value pairs as an aligned block."""
    width = max(len(label) for label, _ in rows)
    return "\n".join(f"{label.ljust(width)}  {value}" for label, value in rows)


def _table(headers: tuple[str, ...], rows: list[tuple[str, ...]], *, empty: str) -> str:
    """Render rows under headers, or ``empty`` when there is nothing to show."""
    if not rows:
        return empty
    widths = [max(len(headers[i]), *(len(row[i]) for row in rows)) for i in range(len(headers))]
    lines = ["  ".join(headers[i].ljust(widths[i]) for i in range(len(headers)))]
    lines.append("  ".join("-" * widths[i] for i in range(len(headers))))
    lines.extend("  ".join(row[i].ljust(widths[i]) for i in range(len(headers))) for row in rows)
    return "\n".join(lines)


def render_job(job: Any, *, as_json: bool) -> str:
    """Render one Job as a labelled block or JSON."""
    if not isinstance(job, dict):
        return _json(job) if as_json else str(job)
    if as_json:
        return _json(job)
    return _block(
        [
            ("id", job.get("id", "")),
            ("name", job.get("name", "")),
            ("description", job.get("description") or ""),
        ]
    )


def render_job_list(jobs: Any, *, as_json: bool) -> str:
    """Render a Job list as an aligned table or JSON."""
    if not isinstance(jobs, list):
        return _json(jobs) if as_json else str(jobs)
    if as_json:
        return _json(jobs)
    return _table(
        ("id", "name", "description"),
        [
            (
                str(job.get("id", "")),
                _truncate(str(job.get("name", ""))),
                _truncate(str(job.get("description") or "")),
            )
            for job in jobs
        ],
        empty="No jobs found.",
    )


def render_customer_outcome(outcome: Any, *, as_json: bool) -> str:
    """Render one Customer Outcome as a labelled block or JSON."""
    if not isinstance(outcome, dict):
        return _json(outcome) if as_json else str(outcome)
    if as_json:
        return _json(outcome)

    customer = outcome.get("customer_value", {})
    business = outcome.get("business_value", {})
    rows = [
        ("id", outcome.get("id", "")),
        ("job_id", outcome.get("job_id", "")),
        ("statement", customer.get("statement", "")),
        ("direction", customer.get("direction", "")),
        ("unit", customer.get("unit_of_measure", "")),
        ("object", customer.get("object_of_control", "")),
        ("importance", _num(customer.get("importance", ""))),
        ("satisfaction", _num(customer.get("satisfaction", ""))),
        (
            "opportunity",
            _num(outcome.get("opportunity_score", customer.get("opportunity_score", ""))),
        ),
        ("category", business.get("category", "")),
        ("business", business.get("statement", "")),
    ]
    width = max(len(label) for label, _ in rows)
    return "\n".join(f"{label.ljust(width)}  {value}" for label, value in rows)


def render_customer_outcome_list(outcomes: Any, *, as_json: bool) -> str:
    """Render a Customer Outcome list as an aligned table or JSON."""
    if not isinstance(outcomes, list):
        return _json(outcomes) if as_json else str(outcomes)
    if as_json:
        return _json(outcomes)
    if not outcomes:
        return "No customer outcomes found."

    headers = ("id", "statement", "importance", "satisfaction", "opportunity")
    rows = [
        (
            str(item.get("id", "")),
            _truncate(str(item.get("customer_value", {}).get("statement", ""))),
            _num(item.get("customer_value", {}).get("importance", "")),
            _num(item.get("customer_value", {}).get("satisfaction", "")),
            _num(item.get("opportunity_score", "")),
        )
        for item in outcomes
    ]
    widths = [max(len(headers[i]), *(len(row[i]) for row in rows)) for i in range(len(headers))]
    lines = ["  ".join(headers[i].ljust(widths[i]) for i in range(len(headers)))]
    lines.append("  ".join("-" * widths[i] for i in range(len(headers))))
    lines.extend("  ".join(row[i].ljust(widths[i]) for i in range(len(headers))) for row in rows)
    return "\n".join(lines)


def render_step(step: Any, *, as_json: bool) -> str:
    """Render one Job-map Step as a labelled block or JSON."""
    if not isinstance(step, dict):
        return _json(step) if as_json else str(step)
    if as_json:
        return _json(step)
    return _block(
        [
            ("id", step.get("id", "")),
            ("job_id", step.get("job_id", "")),
            ("order", step.get("order", "")),
            ("name", step.get("name", "")),
        ]
    )


def render_step_list(steps: Any, *, as_json: bool) -> str:
    """Render a Job map as an ordered table or JSON."""
    if not isinstance(steps, list):
        return _json(steps) if as_json else str(steps)
    if as_json:
        return _json(steps)
    return _table(
        ("order", "id", "name"),
        [
            (
                str(step.get("order", "")),
                str(step.get("id", "")),
                _truncate(str(step.get("name", ""))),
            )
            for step in steps
        ],
        empty="No steps found.",
    )


def render_outcome(outcome: Any, *, as_json: bool) -> str:
    """Render one desired Outcome as a labelled block or JSON."""
    if not isinstance(outcome, dict):
        return _json(outcome) if as_json else str(outcome)
    if as_json:
        return _json(outcome)
    return _block(
        [
            ("id", outcome.get("id", "")),
            ("job_id", outcome.get("job_id", "")),
            ("step_id", outcome.get("step_id") or ""),
            ("statement", outcome.get("statement", "")),
            ("importance", _num(outcome.get("importance", ""))),
            ("satisfaction", _num(outcome.get("satisfaction", ""))),
            ("opportunity", _num(outcome.get("opportunity_score", ""))),
        ]
    )


def render_outcome_list(outcomes: Any, *, as_json: bool) -> str:
    """Render desired Outcomes as an aligned table or JSON."""
    if not isinstance(outcomes, list):
        return _json(outcomes) if as_json else str(outcomes)
    if as_json:
        return _json(outcomes)
    return _table(
        ("id", "statement", "importance", "satisfaction", "opportunity"),
        [
            (
                str(item.get("id", "")),
                _truncate(str(item.get("statement", ""))),
                _num(item.get("importance", "")),
                _num(item.get("satisfaction", "")),
                _num(item.get("opportunity_score", "")),
            )
            for item in outcomes
        ],
        empty="No outcomes found.",
    )


def render_evidence(item: Any, *, as_json: bool) -> str:
    """Render one evidence record as a labelled block or JSON."""
    if not isinstance(item, dict):
        return _json(item) if as_json else str(item)
    if as_json:
        return _json(item)
    return _block(
        [
            ("id", item.get("id", "")),
            ("source", item.get("source_name", "")),
            ("kind", item.get("source_kind", "")),
            ("item_type", item.get("item_type", "")),
            ("name", item.get("name", "")),
            ("job_id", item.get("job_id") or ""),
            ("step_id", item.get("step_id") or ""),
            ("outcome_id", item.get("outcome_id") or ""),
            ("content", item.get("content", "")),
        ]
    )


def render_evidence_list(items: Any, *, as_json: bool) -> str:
    """Render evidence records as an aligned table or JSON."""
    if not isinstance(items, list):
        return _json(items) if as_json else str(items)
    if as_json:
        return _json(items)
    return _table(
        ("id", "source", "item_type", "name"),
        [
            (
                str(item.get("id", "")),
                _truncate(str(item.get("source_name", ""))),
                _truncate(str(item.get("item_type", ""))),
                _truncate(str(item.get("name", ""))),
            )
            for item in items
        ],
        empty="No evidence found.",
    )


def render_saved(verb: str, outcome: Any, *, as_json: bool, noun: str = "Customer outcome") -> str:
    """Confirm a create/update, showing the record by default."""
    if not isinstance(outcome, dict):
        return _json(outcome) if as_json else str(outcome)
    if as_json:
        return _json(outcome)
    return f"{noun} {verb}: {outcome.get('id', '')}"


def render_deleted(outcome_id: str, *, as_json: bool, noun: str = "customer outcome") -> str:
    if as_json:
        return _json({"id": outcome_id, "deleted": True})
    return f"Deleted {noun}: {outcome_id}"


def render_score(importance: float, satisfaction: float, score: float, *, as_json: bool) -> str:
    if as_json:
        return _json(
            {"importance": importance, "satisfaction": satisfaction, "opportunity_score": score}
        )
    return f"Opportunity score: {score:.2f}"

"""Desired Outcomes CLI subcommands.

ODI keeps two outcome shapes: the desired Outcome captured against a Job, and
the Customer Outcome that pairs customer value with business value. This module
owns the former; ``customer-outcomes`` owns the latter.
"""

from __future__ import annotations

from typing import Any

import typer

from agentic_odi_cli.backend import run_tool
from agentic_odi_cli.render import render_deleted, render_outcome, render_outcome_list, render_saved

desired_outcomes_app = typer.Typer(help="Manage desired Outcomes.")

JSON_OPTION = typer.Option(False, "--json", help="Emit machine-readable JSON.")


@desired_outcomes_app.command("add")
def add(
    job_id: str = typer.Option(..., help="Job ID the outcome belongs to"),
    statement: str = typer.Option(..., help="Desired outcome statement"),
    importance: float | None = typer.Option(default=None, min=1.0, max=10.0),
    satisfaction: float | None = typer.Option(default=None, min=1.0, max=10.0),
    step_id: str | None = typer.Option(default=None, help="Optional Step ID"),
    json_output: bool = JSON_OPTION,
) -> None:
    """Add a desired Outcome to a Job."""
    args: dict[str, Any] = {"job_id": job_id, "statement": statement}
    if importance is not None:
        args["importance"] = importance
    if satisfaction is not None:
        args["satisfaction"] = satisfaction
    if step_id is not None:
        args["step_id"] = step_id
    typer.echo(
        render_saved("created", run_tool("add_outcome", args), as_json=json_output, noun="Outcome")
    )


@desired_outcomes_app.command("list")
def list_outcomes(
    job_id: str = typer.Option(..., help="Job ID to list outcomes for"),
    step_id: str | None = typer.Option(default=None, help="Filter by Step ID"),
    json_output: bool = JSON_OPTION,
) -> None:
    """List desired Outcomes for a Job."""
    args: dict[str, Any] = {"job_id": job_id}
    if step_id is not None:
        args["step_id"] = step_id
    typer.echo(render_outcome_list(run_tool("get_outcomes", args), as_json=json_output))


@desired_outcomes_app.command("get")
def get(
    outcome_id: str = typer.Argument(..., help="Outcome ID"), json_output: bool = JSON_OPTION
) -> None:
    """Get a desired Outcome by ID."""
    typer.echo(
        render_outcome(run_tool("get_outcome", {"outcome_id": outcome_id}), as_json=json_output)
    )


@desired_outcomes_app.command("update")
def update(
    outcome_id: str = typer.Argument(..., help="Outcome ID"),
    statement: str | None = typer.Option(default=None, help="New statement"),
    importance: float | None = typer.Option(default=None, min=1.0, max=10.0),
    satisfaction: float | None = typer.Option(default=None, min=1.0, max=10.0),
    step_id: str | None = typer.Option(default=None, help="Move to a Step"),
    json_output: bool = JSON_OPTION,
) -> None:
    """Update a desired Outcome."""
    args: dict[str, Any] = {"outcome_id": outcome_id}
    if statement is not None:
        args["statement"] = statement
    if importance is not None:
        args["importance"] = importance
    if satisfaction is not None:
        args["satisfaction"] = satisfaction
    if step_id is not None:
        args["step_id"] = step_id
    typer.echo(
        render_saved(
            "updated", run_tool("update_outcome", args), as_json=json_output, noun="Outcome"
        )
    )


@desired_outcomes_app.command("delete")
def delete(
    outcome_id: str = typer.Argument(..., help="Outcome ID"),
    yes: bool = typer.Option(False, "--yes", "-y", help="Skip confirmation"),
    json_output: bool = JSON_OPTION,
) -> None:
    """Delete a desired Outcome."""
    if not yes:
        confirm = typer.confirm(f"Delete outcome {outcome_id}?")
        if not confirm:
            raise typer.Exit()
    typer.echo(
        render_deleted(
            run_tool("delete_outcome", {"outcome_id": outcome_id}),
            as_json=json_output,
            noun="outcome",
        )
    )

"""CLI adapter for listing, adding, checking, and ingesting external connectors."""

from __future__ import annotations

import asyncio
import json
import os
from pathlib import Path
from typing import TYPE_CHECKING

import typer

from agentic_odi_cli.backend import run_tool
from agentic_odi_cli.render import render_saved

# The connectors package eagerly imports fastmcp via ``connectors/__init__``.
# Import it lazily so that merely loading the CLI (e.g. ``odi --version``) does
# not pay the fastmcp/mcp import cost. The wrappers below keep stable module
# attributes for tests to monkeypatch.
if TYPE_CHECKING:
    from agentic_odi_connectors.mapping import EvidenceDraft
    from agentic_odi_connectors.models import ConnectorConfig
    from agentic_odi_connectors.protocol import Connector
    from agentic_odi_connectors.registry import ConnectorRegistry
    from agentic_odi_connectors.sink import IngestSink

connectors_app = typer.Typer(
    name="connectors",
    help="Connect Agentic ODI to external systems.",
    no_args_is_help=True,
)


def build_connector(config: ConnectorConfig) -> Connector:
    from agentic_odi_connectors.factory import build_connector as _build_connector

    return _build_connector(config)


def get_default_sink() -> IngestSink:
    from agentic_odi_connectors.sink import get_default_sink as _get_default_sink

    return _get_default_sink()


def drafts_from_batch(
    batch,
    *,
    job_id: str | None = None,
    step_id: str | None = None,
    outcome_id: str | None = None,
) -> list[EvidenceDraft]:
    from agentic_odi_connectors.mapping import drafts_from_batch as _drafts_from_batch

    return _drafts_from_batch(batch, job_id=job_id, step_id=step_id, outcome_id=outcome_id)


def _config_path(config: Path | None) -> Path:
    """Resolve the registry file exactly as the connectors package does.

    The explicit ``--config`` value wins; otherwise the shared resolver owns
    the environment variable and the default location, so the CLI and every
    other entry point read the same file.
    """
    if config is not None:
        return config
    from agentic_odi_connectors.paths import config_path

    return config_path()


def _registry(config: Path | None) -> ConnectorRegistry:
    from agentic_odi_connectors.registry import ConnectorRegistry

    return ConnectorRegistry(_config_path(config))


def _parse_headers(values: list[str] | None) -> dict[str, str]:
    headers: dict[str, str] = {}
    for raw in values or []:
        key, separator, value = raw.partition("=")
        if not separator or not key.strip():
            typer.echo(f"Error: invalid header '{raw}', expected KEY=VALUE", err=True)
            raise typer.Exit(code=1)
        headers[key.strip()] = value.strip()
    return headers


ConfigOption = typer.Option(
    None,
    "--config",
    help="Path to the connectors JSON registry.",
    envvar="AGENTIC_ODI_CONNECTORS_CONFIG",
)

_CONNECTOR_TIMEOUT = 30.0


def _connector_timeout() -> float:
    raw = os.getenv("AGENTIC_ODI_CONNECTOR_TIMEOUT")
    if not raw:
        return _CONNECTOR_TIMEOUT
    try:
        return float(raw)
    except ValueError:
        return _CONNECTOR_TIMEOUT


def _run(coro, name: str):
    """Run a connector coroutine with a bounded timeout and clean failure."""
    timeout = _connector_timeout()
    try:
        return asyncio.run(asyncio.wait_for(coro, timeout=timeout))
    except asyncio.TimeoutError as exc:
        typer.echo(f"Error: connector '{name}' timed out after {timeout:.0f}s", err=True)
        raise typer.Exit(code=1) from exc


@connectors_app.command("list")
def list_connectors(
    config: Path | None = ConfigOption,
) -> None:
    """List configured external connectors."""
    items = _registry(config).list_all()
    if not items:
        typer.echo("No connectors configured.")
        return
    for item in items:
        status = "enabled" if item.enabled else "disabled"
        typer.echo(f"{item.name}\t{item.kind}\t{status}")


@connectors_app.command("catalog")
def catalog_presets(
    area: str | None = typer.Option(None, "--area", help="Filter by capability area."),
    as_json: bool = typer.Option(False, "--json", help="Emit JSON instead of a table."),
) -> None:
    """Browse ready-to-use MCP server presets for common ODI workflows."""
    from agentic_odi_connectors.catalog import AREA_LABELS, UnknownAreaError, list_presets

    try:
        presets = list_presets(area)
    except UnknownAreaError as exc:
        typer.echo(f"Error: {exc}", err=True)
        raise typer.Exit(code=1) from exc
    if as_json:
        typer.echo(json.dumps([preset.model_dump() for preset in presets], indent=2))
        return
    current_area: str | None = None
    for preset in presets:
        if preset.area != current_area:
            if current_area is not None:
                typer.echo()
            current_area = preset.area
            typer.echo(f"{AREA_LABELS[preset.area]} ({preset.area})")
        if preset.auth == "oauth":
            auth = "oauth"
        elif preset.env_vars:
            auth = "api key"
        else:
            auth = "none"
        line = f"  {preset.id:<12} {preset.label:<22} {auth:<8} {preset.url}"
        if preset.env_vars:
            line += f"  [{', '.join(preset.env_vars)}]"
        typer.echo(line)
    typer.echo("\nAdd one with: agentic-odi connectors add mcp --preset <id>")


def _mcp_connector_config(
    *,
    name: str | None,
    url: str | None,
    preset_id: str | None,
    tools: list[str] | None,
) -> ConnectorConfig:
    from agentic_odi_connectors.catalog import (
        UnknownPresetError,
        connector_config_from_preset,
        get_preset,
    )
    from agentic_odi_connectors.models import ConnectorConfig

    if preset_id is not None:
        try:
            preset = get_preset(preset_id)
        except UnknownPresetError as exc:
            typer.echo(f"Error: {exc}", err=True)
            raise typer.Exit(code=1) from exc
        return connector_config_from_preset(preset, name=name, url=url, tools=tools)
    if not url:
        typer.echo("Error: --url is required for MCP connectors (or pass --preset).", err=True)
        raise typer.Exit(code=1)
    if not name:
        typer.echo("Error: --name is required for MCP connectors.", err=True)
        raise typer.Exit(code=1)
    settings: dict[str, object] = {"url": url}
    if tools:
        settings["tools"] = tools
    return ConnectorConfig(name=name, kind="mcp", settings=settings)


@connectors_app.command("add")
def add_connector(
    kind: str = typer.Argument(..., help="Connector kind (mcp, rest, or webhook)."),
    name: str | None = typer.Option(
        None, "--name", help="Unique connector name (defaults to the preset id)."
    ),
    url: str | None = typer.Option(
        None, "--url", help="Endpoint URL (required unless --preset is given)."
    ),
    preset: str | None = typer.Option(
        None, "--preset", help="Preset id from 'connectors catalog'."
    ),
    tool: list[str] | None = typer.Option(  # noqa: B008
        None,
        "--tool",
        help="MCP tool to call during ingest. Repeatable.",
    ),
    method: str | None = typer.Option(None, "--method", help="HTTP method for REST/webhook."),
    header: list[str] | None = typer.Option(  # noqa: B008
        None, "--header", help="HTTP header as KEY=VALUE. Repeatable."
    ),
    records_key: str | None = typer.Option(
        None, "--records-key", help="Dot path to the record list in the response."
    ),
    config: Path | None = ConfigOption,
) -> None:
    """Register a new external connector, optionally from a known preset."""
    from agentic_odi_connectors.models import ConnectorConfig
    from agentic_odi_connectors.registry import DuplicateConnectorError, UnknownConnectorKindError

    if preset is not None and kind != "mcp":
        typer.echo("Error: --preset is only supported for MCP connectors.", err=True)
        raise typer.Exit(code=1)
    if kind == "mcp":
        connector_config = _mcp_connector_config(name=name, url=url, preset_id=preset, tools=tool)
    elif kind in {"rest", "webhook"}:
        if not name:
            typer.echo("Error: --name is required.", err=True)
            raise typer.Exit(code=1)
        if not url:
            typer.echo(f"Error: --url is required for {kind.upper()} connectors.", err=True)
            raise typer.Exit(code=1)
        settings: dict[str, object] = {"url": url}
        if method:
            settings["method"] = method.upper()
        headers = _parse_headers(header)
        if headers:
            settings["headers"] = headers
        if records_key:
            settings["records_key"] = records_key
        connector_config = ConnectorConfig(name=name, kind=kind, settings=settings)
    else:
        if not name:
            typer.echo("Error: --name is required.", err=True)
            raise typer.Exit(code=1)
        connector_config = ConnectorConfig(name=name, kind=kind, settings={})
    try:
        _registry(config).add(connector_config)
    except DuplicateConnectorError as exc:
        typer.echo(f"Error: {exc}", err=True)
        raise typer.Exit(code=1) from exc
    except UnknownConnectorKindError as exc:
        typer.echo(f"Error: {exc}", err=True)
        raise typer.Exit(code=1) from exc
    typer.echo(f"Added {kind} connector '{connector_config.name}'.")
    env_vars = connector_config.settings.get("env_vars") or []
    if env_vars:
        typer.echo(f"Set {', '.join(str(item) for item in env_vars)} before health or ingest.")
    if connector_config.settings.get("auth") == "oauth":
        typer.echo("This server uses OAuth; the browser consent flow runs on first health/ingest.")


@connectors_app.command("health")
def health_connector(
    name: str = typer.Option(..., "--name", help="Connector name."),
    config: Path | None = ConfigOption,
) -> None:
    """Check whether a connector can reach its external system."""
    from agentic_odi_connectors.registry import ConnectorNotFoundError, UnknownConnectorKindError

    try:
        connector_config = _registry(config).get(name)
        connector = build_connector(connector_config)
    except (ConnectorNotFoundError, UnknownConnectorKindError) as exc:
        typer.echo(f"Error: {exc}", err=True)
        raise typer.Exit(code=1) from exc
    status = _run(connector.health(), name)
    typer.echo(status.model_dump_json())
    if not status.ok:
        raise typer.Exit(code=1)


@connectors_app.command("ingest")
def ingest_connector(
    name: str = typer.Option(..., "--name", help="Connector name."),
    job_id: str | None = typer.Option(None, "--job-id", help="Link evidence to a Job."),
    step_id: str | None = typer.Option(None, "--step-id", help="Link evidence to a Step."),
    outcome_id: str | None = typer.Option(
        None, "--outcome-id", help="Link evidence to a desired Outcome."
    ),
    config: Path | None = ConfigOption,
) -> None:
    """Ingest connector records and optionally map them into ODI evidence."""
    from agentic_odi_connectors.registry import ConnectorNotFoundError, UnknownConnectorKindError

    try:
        connector_config = _registry(config).get(name)
        connector = build_connector(connector_config)
    except (ConnectorNotFoundError, UnknownConnectorKindError) as exc:
        typer.echo(f"Error: {exc}", err=True)
        raise typer.Exit(code=1) from exc
    batch = _run(connector.ingest(), name)
    get_default_sink().append(batch)
    typer.echo(batch.model_dump_json())
    if job_id is None and step_id is None and outcome_id is None:
        return
    drafts = drafts_from_batch(batch, job_id=job_id, step_id=step_id, outcome_id=outcome_id)
    for draft in drafts:
        typer.echo(
            render_saved(
                "created",
                run_tool(
                    "add_evidence",
                    {
                        "source_name": draft.source_name,
                        "source_kind": draft.source_kind,
                        "item_type": draft.item_type,
                        "name": draft.name,
                        "content": draft.content,
                        "raw": draft.raw,
                        "job_id": draft.job_id,
                        "step_id": draft.step_id,
                        "outcome_id": draft.outcome_id,
                    },
                ),
                as_json=False,
                noun="Evidence",
            )
        )

"""MCP client connector that ingests tools and resources from an external server."""

from __future__ import annotations

import json
import os
import re
from collections.abc import Mapping
from typing import Any

from fastmcp import Client, FastMCP
from fastmcp.client.transports import StreamableHttpTransport

from agentic_odi_connectors.models import (
    HealthStatus,
    IngestBatch,
    IngestRecord,
    McpConnectorSettings,
)
from agentic_odi_connectors.protocol import Connector

_ENV_VAR_PATTERN = re.compile(r"\$\{([A-Za-z_][A-Za-z0-9_]*)\}")


class MissingEnvironmentError(RuntimeError):
    """Raised when a connector needs credentials that are not in the environment."""

    def __init__(self, names: list[str]) -> None:
        self.names = names
        super().__init__("Missing environment variable(s): " + ", ".join(names))


def _expand_env(value: str, environ: Mapping[str, str]) -> str:
    return _ENV_VAR_PATTERN.sub(lambda match: environ.get(match.group(1), ""), value)


def _to_dict(obj: Any) -> dict[str, Any]:
    if hasattr(obj, "model_dump"):
        dumped = obj.model_dump(mode="json")
        if isinstance(dumped, dict):
            return dumped
    return {"repr": repr(obj)}


def _content_text(obj: Any) -> str:
    parts: list[str] = []
    content = getattr(obj, "content", None)
    if content is None:
        text = getattr(obj, "text", None)
        return text if isinstance(text, str) else json.dumps(_to_dict(obj))
    for item in content:
        text = getattr(item, "text", None)
        if isinstance(text, str):
            parts.append(text)
    return "\n".join(parts) if parts else json.dumps(_to_dict(obj))


class MCPClientConnector(Connector):
    """Pulls catalog, resources, and optional tool results from an MCP server."""

    kind = "mcp"

    def __init__(
        self,
        name: str,
        settings: McpConnectorSettings,
        *,
        server: FastMCP | None = None,
    ) -> None:
        self.name = name
        self.settings = settings
        self._server = server

    def transport(self) -> StreamableHttpTransport | FastMCP:
        """Build the MCP transport, resolving credentials from the environment."""
        if self._server is not None:
            return self._server
        missing = sorted(name for name in self.settings.env_vars if not os.environ.get(name))
        if missing:
            raise MissingEnvironmentError(missing)
        headers = {
            key: _expand_env(value, os.environ) for key, value in self.settings.headers.items()
        }
        return StreamableHttpTransport(
            url=_expand_env(self.settings.url, os.environ),
            headers=headers or None,
            auth="oauth" if self.settings.auth == "oauth" else None,
        )

    def _client(self) -> Client:
        return Client(self.transport())

    async def health(self) -> HealthStatus:
        try:
            async with self._client() as client:
                tools = await client.list_tools()
                resources = await client.list_resources()
            return HealthStatus(
                ok=True,
                message="reachable",
                details={
                    "tool_count": len(tools),
                    "resource_count": len(resources),
                },
            )
        except MissingEnvironmentError as exc:
            return HealthStatus(
                ok=False,
                message=str(exc),
                details={"missing_env": exc.names},
            )
        except Exception as exc:  # noqa: BLE001
            return HealthStatus(ok=False, message=str(exc))

    async def ingest(self) -> IngestBatch:
        batch = IngestBatch(connector_name=self.name)
        try:
            async with self._client() as client:
                tools = await client.list_tools()
                resources = await client.list_resources()
                tool_dicts = [_to_dict(tool) for tool in tools]
                resource_dicts = [_to_dict(resource) for resource in resources]
                catalog_raw = {"tools": tool_dicts, "resources": resource_dicts}
                batch.records.append(
                    IngestRecord(
                        source_name=self.name,
                        source_kind=self.kind,
                        item_type="catalog",
                        name="mcp-catalog",
                        content=json.dumps(catalog_raw, indent=2),
                        raw=catalog_raw,
                    )
                )
                for resource in resources:
                    uri = str(getattr(resource, "uri", ""))
                    name = str(getattr(resource, "name", None) or uri)
                    try:
                        contents = await client.read_resource(uri)
                        content_text = "\n".join(
                            getattr(item, "text", "") or "" for item in contents
                        )
                        batch.records.append(
                            IngestRecord(
                                source_name=self.name,
                                source_kind=self.kind,
                                item_type="resource",
                                name=name,
                                content=content_text,
                                raw={"uri": uri, "resource": _to_dict(resource)},
                            )
                        )
                    except Exception as exc:  # noqa: BLE001
                        batch.errors.append(f"Failed to read resource {uri}: {exc}")
                configured_tools = self.settings.tools
                available = {str(getattr(tool, "name", "")) for tool in tools}
                for tool_name in configured_tools:
                    if tool_name not in available:
                        batch.errors.append(f"Tool not found: {tool_name}")
                        continue
                    try:
                        result = await client.call_tool(tool_name, {})
                        batch.records.append(
                            IngestRecord(
                                source_name=self.name,
                                source_kind=self.kind,
                                item_type="tool_result",
                                name=tool_name,
                                content=_content_text(result),
                                raw={"tool": tool_name, "result": _to_dict(result)},
                            )
                        )
                    except Exception as exc:  # noqa: BLE001
                        batch.errors.append(f"Failed to call tool {tool_name}: {exc}")
        except Exception as exc:  # noqa: BLE001
            batch.errors.append(str(exc))
        return batch

